// CXI: preserve the current location and vehicle when switching renderers.
const skyfallStateFields=['quality','weather','extreme','failmode','blastMode','worldMap','planetRegion','spawn','day'];
function preserveGraphicsState(mode){
 let opts={};for(let id of skyfallStateFields){let el=$(id);if(el)opts[id]=el.value;}
 let chosen=typeof selected==='number'?selected:0;
 location.hash='#'+mode+'~'+encodeURIComponent(JSON.stringify({chosen,opts}));
 location.reload();
}
function restoreGraphicsState(){
 let match=location.hash.match(/^#(?:compat|gpu)~(.+)$/);
 if(!match)return;
 try{
  let saved=JSON.parse(decodeURIComponent(match[1]));
  for(let [id,v] of Object.entries(saved.opts||{})){let el=$(id);if(el&&Array.from(el.options||[]).some(o=>o.value===v))el.value=v;}
  let i=Number(saved.chosen);
  if(Number.isInteger(i)&&i>=0&&i<planes.length){
   selected=i;
   for(let b of hangarCards){let active=Number(b.dataset.i)===selected;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));}
   $('hangarSelected').textContent=planes[selected].name;
  }
 }catch(e){console.warn('Skyfall settings restore unavailable',e);}
}

