if(!compat){function recover(message){running=false;paused=false;$('menu').classList.remove('hide');$('hud').classList.remove('on');$('rendererStatus').textContent=message+' · Reopen 3D or choose compatibility mode.';$('start').disabled=false;$('start').textContent='OPEN COMPATIBILITY MODE';$('start').onclick=()=>preserveGraphicsState('compat')}canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();recover('Graphics context lost');preserveGraphicsState('compat');});window.addEventListener('error',e=>{if(/shader|framebuffer|webgl|GLSL|ERROR: 0:/i.test(e.message||''))recover('Falha no engine 3D')});}

