const PLANET_W=40000000,PLANET_H=20000000,PLANET_T=6000,planetRegions=[["Aurória", -15000000, 1500000], ["Valdênia", -7750000, 6000000], ["Merídia", 5750000, -4000000], ["Nórdara", -14250000, -3000000], ["Oceânia Verde", 13500000, 3250000], ["Eastern Lands", 15500000, -7500000]];
