     let m=t=>side>0?t:Math.PI-t;
     let q=[skin(zz,m(tt-.090),.038),skin(zz+.016,m(tt-.090),.038),skin(zz+.016,m(tt+.081),.038),skin(zz,m(tt+.081),.038)];
