   P(5.15,5.166,.21,.98,SEAM,.012);
   // Small front A330 service doors, far below the cargo bay.
   P(4.10,4.12,-.61,-.33,SEAM,.012);
   P(4.12,4.43,-.61,-.598,SEAM,.012);
   P(4.42,4.44,-.61,-.33,SEAM,.012);
