 function station(z){let i=0;while(i<R.length-2&&R[i+1][0]<z)i++;let a=R[i],b=R[i+1],t=clamp((z-a[0])/(b[0]-a[0]),0,1);return a.map((v,j)=>mix(v,b[j],t));}
