const bombOrder=Object.keys(bombPresets);
let bombs=[],bombStock={},bombKind='moab',bombCam=false,bombLast=null,bombMeshes={},pendingBombBursts=[];
function refillBombs(){bombStock=Object.fromEntries(bombOrder.map(k=>[k,bombPresets[k].stock]));}
function resetBomber(){bombs=[];pendingBombBursts=[];refillBombs();bombKind=bombPresets[$('bombChoice').value]?$('bombChoice').value:'moab';bombCam=false;bombLast=null;}
function chooseBomb(k){if(!bombPresets[k])return;bombKind=k;$('bombChoice').value=k;updateWeaponHUD();}
function nextBomb(){let i=bombOrder.indexOf(bombKind);chooseBomb(bombOrder[(i+1)%bombOrder.length]);alertEvent('SELECTED: '+bombPresets[bombKind].label);}
function releaseBomb(){
 if(!p.bomber||dead||paused||state.ground||state.water||!bombStock[bombKind]||bombs.filter(b=>!b.done).length>=5)return;
 let profile={...bombPresets[bombKind]};
 if(bombKind==='nuclear'){let v=Math.floor(Math.random()*3);profile.power=[4.5,5.1,5.8][v];profile.heat=[2.1,2.7,3.1][v];profile.label=['NUCLEAR · AURORA','NUCLEAR · INFERNO','NUCLEAR · TITAN'][v];}
 let b=basis(state.yaw,state.pitch,state.roll),pos=localToWorld(V(0,-1.45,0),state.pos,b,p.scale);
 let obj={kind:bombKind,profile,pos:[...pos],origin:[...pos],yaw:state.yaw,age:0,done:false};
 bombStock[bombKind]--;bombs.push(obj);bombLast=obj;alertEvent('EFFECT DEPLOYED: '+profile.label);updateWeaponHUD();
}
// A small number of staggered secondary blasts makes every preset visually distinct.
function scheduleBombBurst(pos,medium,profile,delay,powerMul=1,dx=0,dz=0,shader=profile.shader){
 if(pendingBombBursts.length>=32)return;
 let bp={...profile,shader,cinematicCloud:false,heat:profile.heat*(powerMul<.8?.75:1)};
 pendingBombBursts.push({at:simTime+delay,pos:[pos[0]+dx,pos[1]+.14,pos[2]+dz],medium,power:profile.power*powerMul,profile:bp});
}
function bombSequence(pos,medium,profile){
 let k=profile.pattern,P=profile.power;
 let bursts=profile.moabWhite?2:k==='cluster'?7:k==='vortex'?6:k==='plasma'?4:k==='meteor'?4:k==='mushroom'?2:3;
 for(let i=0;i<bursts;i++){
  let a=i*2.39996+Math.random()*.36,r=k==='cluster'?P*(2.0+i*.55):k==='vortex'?P*2.2:k==='meteor'?P*(1.5+i*.65):k==='cryo'?P*.9:P*(.30+i*.30);
  let x=Math.cos(a)*r,z=Math.sin(a)*r;
  if(k==='pulse'||k==='emp'||k==='plasma'||k==='mushroom')x=z=0;
  let delay=profile.moabWhite?.16+i*.30:k==='cluster'?.12+i*.095:k==='vortex'?.16+i*.17:k==='plasma'?.15+i*.24:k==='meteor'?.10+i*.19:.22+i*.30;
  let size=profile.moabWhite?.46:k==='cluster'?.34:k==='meteor'?.42:k==='vortex'?.37:k==='mushroom'?.58:.45+i*.08;
  let shader=k==='cryo'||k==='dust'?0:k==='emp'?2:k==='plasma'||k==='fire'||k==='meteor'?1:profile.shader;
  scheduleBombBurst(pos,medium,profile,delay,size,x,z,shader);
 }
 if(medium===0&&(k==='shock'||k==='pulse'||k==='emp'||k==='plasma'||k==='dust'||k==='mushroom'))
  shockwaves.push({pos:[...pos],age:0,power:P*(k==='emp'?1.3:1)});
}
function triggerBombBurst(q){
 structureBlast(q.pos,Math.min(200,24+q.power*17),q.power*.065,12);
 secondaryBlasts.push({medium:q.medium,pos:q.pos,age:0,power:q.power,dir:V(0,0,1),profile:q.profile,cinematic:false,seed:rnd(0,6.28)});if(secondaryBlasts.length>24)secondaryBlasts.splice(0,secondaryBlasts.length-24);
 // Different particles: smoke for dust/cryo/vortex, luminous sparks for plasma/meteor, thermal flames for fire.
 let k=q.profile.pattern,n=quality===0?7:quality===1?12:18;
 for(let i=0;i<n;i++){
  let d=norm(randVec(1)),v=add(mul(d,rnd(3,15)*q.power),V(0,rnd(0,4)*q.power,0));
  let fire=(q.profile.moabWhite||k==='dust'||k==='cryo'||k==='vortex'||k==='emp')?0:k==='plasma'||k==='meteor'?rnd(.7,1):rnd(.25,.85);
  addParticle(add(q.pos,randVec(q.power*.7)),v,rnd(.18,.66)*q.power,rnd(.9,2.5),fire,rnd(.4,1.2)*q.power);
 }
}
// Fictional visual animation only; no real-world ballistics or blast calculations.
function stepBomber(dt){
 if(!p.bomber)return;
 for(let b of bombs){if(b.done)continue;b.age+=dt;let floor=surfaceAt(b.pos[0],b.pos[2]),a=Math.min(1,b.age/4);b.pos[1]=mix(b.origin[1],floor,a*a);
  if(a>=1){b.done=true;b.until=simTime+14;let pt=[b.pos[0],floor+.15,b.pos[2]],power=b.profile.power,medium=explosionMedium(pt,true);b.pos=pt;
   if(medium===2)blastSplash(pt,power);
   secondaryBlasts.push({medium,pos:pt,age:0,power,dir:V(0,0,1),profile:b.profile,cinematic:false,seed:rnd(0,6.28)});if(secondaryBlasts.length>24)secondaryBlasts.splice(0,secondaryBlasts.length-24);
   flash=Math.max(flash,b.kind==='emp'?.30:b.kind==='nuclear'?.88:.55);
   let count=quality===0?17:quality===1?29:40;
   for(let i=0;i<count;i++){let d=norm(randVec(1)),fire=(b.kind==='moab'||['cryo','seismic','emp','vortex'].includes(b.kind))?0:rnd(.4,1);
    addParticle(add(pt,randVec(power)),mul(d,rnd(8,22)*power),rnd(.2,.85)*power,rnd(.7,2.5),fire,.7);}
   structureBlast(pt,Math.min(450,65+power*37),Math.min(1.35,power*.23),58);bombSequence(pt,medium,b.profile);
   queueWave(pt,power,'bomb:'+b.kind);alertEvent('DETONATION: '+b.profile.label);
  }
 }
 // The scheduler is bounded and decoupled from the terrain/vehicle rendering pipeline.
 for(let i=pendingBombBursts.length-1;i>=0;i--)if(simTime>=pendingBombBursts[i].at){triggerBombBurst(pendingBombBursts[i]);pendingBombBursts.splice(i,1);}
 bombs=bombs.filter(b=>!b.done||simTime<b.until);
 if(dead)bombCam=false;
 if(bombCam&&(!bombLast||bombLast.done&&simTime>bombLast.until)){bombCam=false;camPos=null;}
}
function bomberCamera(){if(!p.bomber||!bombCam||!bombLast||dead)return null;let b=bombLast;if(!b.done)return {desired:add(b.pos,V(32,21,-38)),look:add(b.pos,V(0,-9,0))};let r=80*b.profile.power;return {desired:add(b.pos,V(r*.8,r*.48,-r)),look:add(b.pos,V(0,r*.24,0))};}
function drawBombs(drawMesh){if(!p.bomber)return;for(let b of bombs){if(b.done)continue;if(!bombMeshes[b.kind]){let sh=shape();sh.smoothTube([[-1.7,.03,0,0],[-1.3,.26,0,0],[.85,.32,0,0],[1.4,.23,0,0],[1.7,.01,0,0]],b.profile.color,16);for(let side of [-1,1]){airfoil(sh,[[side*.19,0,-1.0,.62,.06],[side*.48,0,-1.35,.3,.03]],[.22,.25,.27],false);}bombMeshes[b.kind]=sh.finish();}drawMesh(bombMeshes[b.kind],b.pos,basis(b.yaw,-1.35,0),b.profile.scale);}}
function resetTraining(){resetBomber();training=[];missiles=[];const cfg=p.fighter?loadoutPresets[loadout]:loadoutPresets.none;ammo=cfg.normal;locked=null;specialAmmo=cfg.special;piloted=null;shotView=null;$('targetMark').style.display='none';$('weaponHud').style.display=p.fighter?'block':'none';$('loadoutControls').textContent=p.bomber?'K: cycle bombs · 7/8/9: quick select · SPACE: drop · Z: camera':p.missile?'WASD: steer · SPACE: detonate · C: camera':p.fighter?(loadout==='none'?'F-16 · free flight':cfg.hint+' · Y: recarregar'):'';if(!p.fighter||!state||loadout==='none')return;let b=basis(state.yaw,state.pitch,state.roll);for(let i=0;i<3;i++){let origin=add(state.pos,add(mul(b.f,550+i*220),add(mul(b.r,(i-1)*100),V(0,Math.max(120,900-state.pos[1])+i*35,0))));training.push({name:'DRONE '+(i+1),origin,pos:[...origin],phase:i*2,alive:true});}}
function selectTraining(){if(!p.fighter||dead||paused)return;let list=training.filter(t=>t.alive);if(!list.length){locked=null;return}locked=list[(list.indexOf(locked)+1)%list.length];alertEvent('ALVO DE TREINO: '+locked.name);updateWeaponHUD()}
function updateWeaponHUD(){let el=$('weaponHud');if(p.bomber){el.style.display='block';el.textContent='BOMBER · '+bombPresets[bombKind].label+' ×'+(bombStock[bombKind]||0)+' · K: next · 7/8/9: quick select · SPACE: drop · Z: cam · Y: reload';return;}if(p.missile){el.style.display='block';el.textContent=dead?'CINEMATIC IMPACT · R: restart · zoom: mouse':(state.pos[1]>=SPACE_EDGE?'SPACE':'PILOTABLE MISSILE')+' · WASD · SHIFT/CTRL · J: fast travel '+(spaceWarp?'ON':'OFF')+' · SPACE: detonate';return;}el.style.display=p.fighter?'block':'none';if(!p.fighter)return;el.textContent=piloted?'SPECIAL MISSILE CAMERA · WASD: steer · SPACE: end effect · C: return':shotView?'CINEMATIC IMPACT · C: return to aircraft':loadout==='none'?'FREE FLIGHT · NO MISSILES':[loadoutPresets[loadout].normal?'NORMAIS '+ammo+'/4 · SPACE':null,loadoutPresets[loadout].special?'ESPECIAL '+specialAmmo+'/1 · X':null,'Y: recarregar'].filter(Boolean).join(' · ');}
function launchTraining(special=false){if(!p.fighter||dead||paused||state.water||state.ground||(special?!specialAmmo:!ammo)||state.missing.size||piloted)return;let b=basis(state.yaw,state.pitch,state.roll),side=ammo%2?1:-1,origin=localToWorld(V(special?0:side*2.25,-.5,-.75),state.pos,b,p.scale);let m={pos:[...origin],age:0,trail:0,b,yaw:state.yaw,pitch:clamp(state.pitch,-1.25,1.25),special};missiles.push(m);if(special){specialAmmo--;piloted=m;shotView=null;camPos=null;keys.clear();alertEvent('SPECIAL — CAMERA ACTIVE');}else{ammo--;alertEvent('STANDARD MISSILE LAUNCHED');}boom(.12,'metal');updateWeaponHUD()}
function endMissile(m){if(m.done)return;m.done=true;cinematicMissileImpact(m.pos,m.special);if(m===piloted){piloted=null;shotView={point:[...m.pos],yaw:m.yaw,until:simTime+7};camPos=null;keys.clear();}alertEvent(m.special?'IMPACTO ESPECIAL':'MISSILE IMPACT');}
function missileCamera(){if(dead)return null;let bm=bomberCamera();if(bm)return bm;if(p.missile&&cameraMode===0){let b=basis(state.yaw,state.pitch,state.roll);if(state.pos[1]>21000)return spaceCamera(state,b);return {desired:add(state.pos,add(mul(b.f,-10*p.scale/1.4),mul(b.u,2.7*p.scale/1.4))),look:add(state.pos,mul(b.f,4))};}if(piloted){let m=piloted;return {desired:add(m.pos,add(mul(m.b.f,-12),V(0,3,0))),look:add(m.pos,mul(m.b.f,30))};}if(shotView){let a=shotView.yaw,pt=shotView.point;return {desired:add(pt,V(-Math.sin(a)*185,95,-Math.cos(a)*185)),look:add(pt,V(0,23,0))};}return null;}
function stepTraining(dt){if(!p.fighter)return;if(dead){piloted=null;shotView=null;}if(shotView&&simTime>=shotView.until){shotView=null;camPos=null;keys.clear();}for(let t of training){if(!t.alive)continue;t.pos=add(t.origin,V(Math.sin(simTime*.55+t.phase)*78,Math.sin(simTime*.36+t.phase)*23,Math.cos(simTime*.55+t.phase)*92));}for(let m of missiles){if(m.done)continue;m.age+=dt;if(m===piloted){let key=(...a)=>a.some(k=>keys.has(k));m.yaw+=((key('d','arrowright')?1:0)-(key('a','arrowleft')?1:0))*dt*1.3;m.pitch=clamp(m.pitch+((key('w','arrowup')?1:0)-(key('s','arrowdown')?1:0))*dt*1.1,-1.35,1.35);m.b=basis(m.yaw,m.pitch,0);}m.pos=add(m.pos,mul(m.b.f,dt*(m.special?210:310)));m.trail+=dt;if(m.trail>.06){m.trail=0;emitRocketPlume(add(m.pos,mul(m.b.f,-.9)),m.b.f,mul(m.b.f,m.special?24:18),m.special?1.15:.82,m.special?1.22:1.0)}let h=surfaceAt(m.pos[0],m.pos[2]);if(m.pos[1]<=h){m.pos[1]=h;endMissile(m);continue;}for(let t of training){if(t.alive&&Math.hypot(...sub(t.pos,m.pos))<12){t.alive=false;endMissile(m);if(locked===t)locked=null;break;}}if(!m.done&&m.age>(m.special?38:12)){if(m.special)endMissile(m);else m.done=true;}}missiles=missiles.filter(m=>!m.done);}
function cinematicMissileImpact(point,special=false){
 let power=special?3.6:rnd(.72,.91),dir=V(0,0,1),dist=Math.hypot(...sub(camPos||state.pos,point));
 let medium=explosionMedium(point);if(medium===2)blastSplash(point,power);secondaryBlasts.push({medium,pos:[...point],age:0,power,dir,cinematic:true,special,seed:rnd(0,6.28)});
 flash=Math.max(flash,clamp(95/Math.max(35,dist),.07,.48));
 for(let j=0;j<(quality===0?25:quality===1?40:56);j++){
  let d=norm(randVec(1)),speed=rnd(17,49),v=mul(d,speed*power);
  addParticle(add(point,mul(d,rnd(.2,2))),v,rnd(.18,.46)*power,rnd(.23,1.04),rnd(.88,1),rnd(.08,.4));
 }
 for(let j=0;j<(quality===0?8:14);j++){
  let d=norm(randVec(1));addParticle(add(point,mul(d,2)),add(mul(d,rnd(3,10)),V(0,1.3,0)),rnd(1.4,3.1)*power,rnd(3.5,7.4),0,rnd(1.1,2.3));
  if(j<7)chunks.push({pos:[...point],vel:mul(d,rnd(12,26)),rot:randVec(3),spin:randVec(5),size:rnd(.13,.39),age:22});
 }
 queueWave(point,power,'missile');
}
function trainingMeshes(){if(trainMesh)return;let sh=shape();sh.smoothTube([[-2.3,.10,0,0],[-1.7,.41,0,0],[1.1,.42,0,0],[2.25,.02,0,0]],[.66,.62,.49],16);for(let side of [-1,1])airfoil(sh,[[side*.3,0,.4,1.6,.08],[side*2.5,.10,-.65,.60,.04]],[.51,.52,.49],false);finFoil(sh,.12,.8,-1.2,-1.85,.85,.38,[.65,.30,.17]);trainMesh=sh.finish();sh=shape();sh.smoothTube([[-1.2,.10,0,0],[.72,.11,0,0],[1.2,.015,0,0]],[.85,.85,.78],12);for(let side of [-1,1]){airfoil(sh,[[side*.06,0,-.65,.40,.025],[side*.25,0,-.83,.20,.015]],[.37,.39,.40],false);}missileMesh=sh.finish();}
// Arcade-only enemy towers. Positions are invented procedural scenery, not real locations.
let arcadeTowers=[],towerTile='',towerSpawn=null,towerClock=7,towerShot=null,gunBurst=null,gunClock=0,towerMesh=null,towerGunMesh=null,towerBoltMesh=null,towerRocketMesh=null,towerRackMesh=null;
function resetTowers(){arcadeTowers=[];towerTile='';towerSpawn=null;towerClock=7;towerShot=null;gunBurst=null;gunClock=0;}
function refreshTowers(){if(worldMode!==1||!state||!towerSpawn)return;let step=WAR_CITY_TILE,ix=Math.floor(state.pos[0]/step),iz=Math.floor(state.pos[2]/step),key=ix+','+iz;if(key===towerTile)return;towerTile=key;arcadeTowers=[];for(let j=-2;j<=2;j++)for(let i=-2;i<=2;i++){for(let city of cityCell(ix+i,iz+j)){let x=city.x,z=city.z;if(oceanAt(x,z)||height(x,z)<12||Math.hypot(x-towerSpawn[0],z-towerSpawn[2])<3500||Math.hypot(x,z+1100)<3500)continue;let r=rng(city.seed^512983);arcadeTowers.push({id:city.id+':tower',pos:V(x,height(x,z)+.1,z),heading:r()*6.28,kind:r()<.48?'missile':'gun'});}}}
function initTowerMeshes(){if(towerMesh)return;let sh=shape();sh.box(0,.45,0,8,.9,8,[.24,.27,.25]);sh.box(0,1.25,0,5.5,.7,5.5,[.37,.40,.34]);sh.box(0,2.1,0,2.5,1.1,2.5,[.27,.31,.27]);towerMesh=sh.finish();sh=shape();sh.box(0,0,0,2.2,1.15,2.4,[.36,.40,.33]);for(let i=0;i<6;i++){let a=i*Math.PI/3;sh.box(Math.cos(a)*.48,Math.sin(a)*.48,2,.22,.22,3.4,[.23,.27,.26]);}sh.box(0,0,3.4,1.16,1.16,.24,[.20,.23,.22]);towerGunMesh=sh.finish();sh=shape();sh.box(0,0,0,.48,.48,6,[1,.66,.19]);towerBoltMesh=sh.finish();sh=shape();sh.box(0,0,0,2.8,1.15,2.5,[.31,.36,.31]);for(let i of [-1,1])for(let j of [-1,1])sh.box(i*.57,j*.39,1.45,.79,.73,3.1,[.42,.46,.40]);towerRackMesh=sh.finish();sh=shape();sh.smoothTube([[-2.5,.05,0,0],[-2.1,.30,0,0],[1.6,.30,0,0],[2.55,.015,0,0]],[.74,.77,.72],14);for(let side of [-1,1]){airfoil(sh,[[side*.25,0,-1.4,.9,.06],[side*.66,0,-1.9,.32,.04]],[.29,.32,.29],false);}towerRocketMesh=sh.finish();}
// Scripted visual arc only: the game damage event is independent of projectile geometry.
function towerEffectPoint(q,f){let pos=q.origin.map((v,k)=>mix(v,state.pos[k],f));if(q.kind==='missile')pos[1]+=Math.sin(Math.PI*f)*q.arc;return pos;}
function drawTowers(drawMesh){if(worldMode!==1||!state)return;refreshTowers();initTowerMeshes();let eye=camPos||state.pos;for(let t of arcadeTowers){if(Math.hypot(t.pos[0]-eye[0],t.pos[2]-eye[2])>3800)continue;drawMesh(towerMesh,t.pos,basis(0,0,0),1);drawMesh(t.kind==='missile'?towerRackMesh:towerGunMesh,add(t.pos,V(0,2.9,0)),basis(t.heading,t.kind==='missile'?.75:.32,0),1);}if(towerShot){let q=towerShot,f=clamp(q.age/q.duration,0,1),pos=towerEffectPoint(q,f),prev=towerEffectPoint(q,Math.max(0,f-.02)),dv=sub(pos,prev),yaw=Math.atan2(dv[0],dv[2]),pitch=Math.atan2(dv[1],Math.hypot(dv[0],dv[2]));drawMesh(towerRocketMesh,pos,basis(yaw,pitch,0),2.2);}if(gunBurst){let q=gunBurst;for(let i=0;i<8;i++){let f=((q.age*2.4+i/8)%1);drawMesh(towerBoltMesh,towerEffectPoint(q,f),basis(0,.65,0),1.2);}}}
function spillBomberInventory(){if(!p.bomber)return 0;let n=0,total=0;for(let kind of bombOrder){let count=bombStock[kind]||0;total+=count;for(let i=0;i<count&&n<7;i++){let profile={...bombPresets[kind]},pos=add(state.pos,V((n-2)*4,-2-n*.7,(n%2?1:-1)*5));bombs.push({kind,profile,pos:[...pos],origin:[...pos],yaw:state.yaw,age:0,done:false});n++;}bombStock[kind]=0;}if(total)alertEvent('REMAINING PAYLOAD RELEASED: '+total);return n;}
// Game-only exclusion: civilian and unarmed transport aircraft are never attacked.
function arcadeDefenseExcluded(aircraft){return !aircraft||!(aircraft.fighter||aircraft.bomber||aircraft.missile);}
function towerHit(roll=Math.random(),kind='gun'){if(dead||!state||arcadeDefenseExcluded(p)||(p.titan&&kind==='gun'))return;if(p.missile){alertEvent((kind==='missile'?'MISSILE':'TORRE')+' · PILOTABLE MISSILE ATINGIDO');detonatePilotable([...state.pos]);return;}let label=kind==='missile'?'MISSILE':'TORRE',available=['left','right'].filter(k=>!state.missing.has(k));if(kind==='missile'||roll<.5||!available.length){alertEvent(label+' · MID-AIR EXPLOSION');spillBomberInventory();explode(null,true);}else{let wing=available[Math.floor(Math.random()*available.length)];alertEvent(label+' · ASA ATINGIDA');detach(wing);}}
function stepTowers(dt){if(worldMode!==1||!state||dead||arcadeDefenseExcluded(p)||p.groundVehicle||state.ground||state.water){towerShot=null;gunBurst=null;gunClock=0;return;}refreshTowers();let near=arcadeTowers.filter(t=>Math.hypot(t.pos[0]-state.pos[0],t.pos[2]-state.pos[2])<3300),low=state.pos[1]<=height(state.pos[0],state.pos[2])+2600;
// Independent scripted arcade minigun effect; no ballistic simulation.
gunClock=Math.max(0,gunClock-dt);if(p.titan)gunBurst=null;if(gunBurst){let q=gunBurst;q.age+=dt;q.trail+=dt;if(q.trail>.14){q.trail=0;addParticle(q.origin,V(0,2,0),1.4,.20,.95,1);}if(q.age>=q.duration){gunBurst=null;gunClock=1.2;towerHit(Math.random(),'gun');}}else if(!p.titan&&low&&gunClock<=0){let t=near.find(t=>t.kind==='gun');if(t){gunBurst={origin:add(t.pos,V(0,4,0)),age:0,duration:1.25,kind:'gun',trail:0};alertEvent('ALERTA · RAJADA DE MINIGUN');addParticle(gunBurst.origin,V(0,2,0),1.4,.25,.95,1);}}if(dead)return;
if(towerShot){let q=towerShot;q.age+=dt;q.trail+=dt;if(q.trail>.12){q.trail=0;let pos=towerEffectPoint(q,clamp(q.age/q.duration,0,1));addParticle(pos,V(0,.4,0),2.0,2.1,0,2.4);addParticle(pos,V(0,0,0),.85,.26,.95,1);}if(q.age>=q.duration){towerShot=null;towerHit(Math.random(),q.kind);towerClock=11+Math.random()*5;}return;}towerClock-=dt;if(towerClock>0)return;let candidate=near.find(t=>t.kind==='missile');if(!candidate||!low){towerClock=2;return;}towerShot={origin:add(candidate.pos,V(0,4,0)),age:0,duration:3.3,kind:'missile',arc:110,trail:0};alertEvent('WARNING · INCOMING MISSILE');addParticle(towerShot.origin,V(0,3,0),3,.45,.95,1);}



