 flightWarnPreviousFeet=s.ground?null:feet;
 let node=$('flightWarning');node.classList.toggle('on',!!key);node.classList.toggle('danger',!!key&&!!flightWarningDefs[key][2]);
 if(key){let def=flightWarningDefs[key];$('flightWarningTitle').textContent=def[0];$('flightWarningDetail').textContent=def[1]+(top.note?' • '+top.note:'');$('flightWarningOther').textContent=alerts.slice(1,4).map(a=>flightWarningDefs[a.key][0]).join('  ·  ');flightWarnPending='';}
