const ROAD_MOTORS={three:{limit:6877,idle:850,cyl:3,pulse:146,over:315,rough:.062,res:[112,246,475,890],exhaust:.62,mech:.20,air:.22},four:{limit:6877,idle:780,cyl:4,pulse:110,over:254,rough:.028,res:[89,190,390,740],exhaust:.79,mech:.11,air:.27},suv:{limit:6200,idle:810,cyl:4,pulse:93,over:211,rough:.038,res:[76,178,330,620],exhaust:.86,mech:.15,air:.35},pickup:{limit:6200,idle:760,cyl:6,pulse:80,over:167,rough:.072,res:[57,132,290,530],exhaust:1.0,mech:.20,air:.23},diesel:{limit:2505,idle:620,cyl:6,pulse:67,over:162,rough:.11,res:[48,107,285,680],exhaust:.88,mech:.39,air:.26},bus:{limit:2505,idle:680,cyl:6,pulse:88,over:204,rough:.069,res:[68,143,351,820],exhaust:.70,mech:.29,air:.41}};
