function roadHitShape(s,v,pos=s.pos,yaw=s.yaw){let co=Math.cos(yaw),si=Math.sin(yaw),parts=[],bounds=[Infinity,Infinity,-Infinity,-Infinity],pitch=s.pitch||0,roll=s.roll||0,base=roadHitProfiles[detailedRoadKey(v)];
 function addPart(poly,lo,hi,kind){let pts=[],box=[Infinity,Infinity,-Infinity,-Infinity],bottom=Infinity,top=-Infinity;for(let [x,z] of poly){let X=pos[0]+x*co+z*si,Z=pos[2]-x*si+z*co,dy=z*Math.sin(pitch)-x*Math.sin(roll);pts.push([X,Z]);box[0]=Math.min(box[0],X);box[1]=Math.min(box[1],Z);box[2]=Math.max(box[2],X);box[3]=Math.max(box[3],Z);bottom=Math.min(bottom,pos[1]+lo+dy);top=Math.max(top,pos[1]+hi+dy);}for(let i=0;i<2;i++){bounds[i]=Math.min(bounds[i],box[i]);bounds[i+2]=Math.max(bounds[i+2],box[i+2]);}parts.push({kind,pts,box,lo:bottom,hi:top});}
 for(let q of base){if(s.detachedRoadParts?.[q.kind])continue;addPart(q.poly,q.lo,q.hi,q.kind);}
 let m=meshes[planes.indexOf(v)];for(let i=0;i<m.wheels.length;i++){if(s.lostWheels?.has(i))continue;let w=m.wheels[i],turn=w.front?(s.steer||0):0,c=Math.cos(turn),sn=Math.sin(turn),a=w.width*.5,r=w.r,poly=[[-a,-r],[a,-r],[a,r],[-a,r]].map(([x,z])=>[w.x+x*c+z*sn,w.z-x*sn+z*c]),y=s.wheelTravel?.[i]||0;addPart(poly,y-r,y+r,'wheel'+i);}
 return {parts,box:bounds};}
function roadBoxesOverlap(a,b){return a[0]<b[2]&&a[2]>b[0]&&a[1]<b[3]&&a[3]>b[1];}
function roadProject(p,x,z){let lo=Infinity,hi=-Infinity;for(let a of p){let v=a[0]*x+a[1]*z;lo=Math.min(lo,v);hi=Math.max(hi,v);}return [lo,hi];}
function roadPartSAT(a,b){if(a.hi<=b.lo||b.hi<=a.lo||!roadBoxesOverlap(a.box,b.box))return null;let best=Infinity,n=null;for(let p of [a.pts,b.pts])for(let i=0;i<p.length;i++){let u=p[i],v=p[(i+1)%p.length],dx=v[0]-u[0],dz=v[1]-u[1],l=Math.hypot(dx,dz);if(l<.00001)continue;let x=-dz/l,z=dx/l,A=roadProject(a.pts,x,z),B=roadProject(b.pts,x,z),ab=A[1]-B[0],ba=B[1]-A[0];if(ab<=.0001||ba<=.0001)return null;if(Math.min(ab,ba)<best){best=Math.min(ab,ba);n=ab<=ba?[x,z]:[-x,-z];}}if(!n)return null;
 let [x,z]=n,tx=-z,tz=x,A=roadProject(a.pts,x,z),B=roadProject(b.pts,x,z),T=roadProject(a.pts,tx,tz),U=roadProject(b.pts,tx,tz),plane=(A[1]+B[0])*.5;
 // Contact on the selected separating face, not the center of a long bus.
 let face=(p,edge,sign)=>{let v=p.filter(q=>Math.abs(q[0]*x+q[1]*z-edge)<.065);return roadProject(v.length?v:p,tx,tz);},F=face(a.pts,A[1],1),G=face(b.pts,B[0],-1),low=Math.max(F[0],G[0]),high=Math.min(F[1],G[1]),t=low<=high?(low+high)*.5:clamp((low+high)*.5,Math.max(T[0],U[0]),Math.min(T[1],U[1]));return {a,b,n,depth:best,point:V(x*plane+tx*t,(Math.max(a.lo,b.lo)+Math.min(a.hi,b.hi))*.5,z*plane+tz*t)};}
function roadPairHit(A,B){if(!roadBoxesOverlap(A.box,B.box))return null;let solid=null,mirror=null;for(let a of A.parts)for(let b of B.parts){let q=roadPartSAT(a,b);if(!q)continue;if(a.kind.endsWith('Mirror')||b.kind.endsWith('Mirror')){if(!mirror||q.depth>mirror.depth)mirror=q;}else if(!solid||q.depth>solid.depth)solid=q;}return solid||mirror;}
function roadBuildingShape(b){let x=b.x-b.w*.5,z=b.z-b.d*.5,X=b.x+b.w*.5,Z=b.z+b.d*.5,box=[x,z,X,Z],level=structureDamage.get(b.structureId)||0,part={kind:'wall',box,pts:[[x,z],[X,z],[X,Z],[x,Z]],lo:b.y,hi:b.y+structureHeight(b,level)};return {box,parts:[part]};}
function roadBuildingCandidates(box,x,z){let region=roadIndex(x,z),set=new Set();for(let i=Math.floor(box[0]/100);i<=Math.floor(box[2]/100);i++)for(let j=Math.floor(box[1]/100);j<=Math.floor(box[3]/100);j++)for(let b of region.cells.get(i+','+j)||[])if(!set.has(b)&&(structureDamage.get(b.structureId)||0)<.94&&roadBoxesOverlap(box,[b.x-b.w*.5,b.z-b.d*.5,b.x+b.w*.5,b.z+b.d*.5]))set.add(b);return [...set].map(roadBuildingShape);}
function roadSweepCollision(s,v,old,oldYaw,player){let end=[...s.pos],yaw=s.yaw,dist=Math.hypot(end[0]-old[0],end[2]-old[2]),turn=Math.atan2(Math.sin(yaw-oldYaw),Math.cos(yaw-oldYaw)),radius=Math.hypot(v.span,v.body)*.5+1,box=[Math.min(old[0],end[0])-radius,Math.min(old[2],end[2])-radius,Math.max(old[0],end[0])+radius,Math.max(old[2],end[2])+radius],candidates=roadBuildingCandidates(box,end[0],end[2]);if(!candidates.length)return false;let nSteps=Math.max(1,Math.ceil((dist+Math.abs(turn)*radius+Math.abs(end[1]-old[1]))/.28));for(let i=1;i<=nSteps;i++){let f=i/nSteps,pos=old.map((a,j)=>mix(a,end[j],f)),y=oldYaw+turn*f,shape=roadHitShape(s,v,pos,y);for(let b of candidates){let hit=roadPairHit(shape,b);if(!hit)continue;let normal=V(-hit.n[0],0,-hit.n[1]),speed=Math.max(0,-dot(s.carVel,normal));if(hit.a.kind.endsWith('Mirror')){if(speed>3)launchRoadPart(s,v,hit.a.kind,hit.point,normal,Math.max(5,speed));continue;}
 s.pos=add(pos,mul(normal,Math.min(hit.depth+.015,.8)));s.yaw=y;let vn=dot(s.carVel,normal);if(vn<0)s.carVel=add(s.carVel,mul(normal,-vn*1.07));let friction=1-clamp(speed*.012,.035,.24);s.carVel[0]*=friction;s.carVel[2]*=friction;if(speed>1.8){let r=sub(hit.point,s.pos);s.yawRate=(s.yawRate||0)+clamp((r[2]*normal[0]-r[0]*normal[2])*speed*.026,-1.6,1.6);if(player){roadDamage(s,speed,hit.point,normal);if(speed>3&&simTime-structureLastRoadHit>.25){structureLastRoadHit=simTime;structureBlast(hit.point,Math.max(4,Math.min(19,speed*.70)),clamp(speed/36,.12,.95),5);}}else if(simTime-(s.lastHit??-10)>.35){s.lastHit=simTime;trafficRoadDamage(s,v,speed,hit.point,normal,30);}}return true;}}return false;}

